define("local_yandexcaptcha/captcha", ["core/notification"], function(Notification) {
    return {
        widgetId: null,

        init: function(sitekey, containerId) {
            var self = this;
            var attempts = 0;
            var maxAttempts = 50;

            var checkInterval = setInterval(function() {
                attempts++;

                if (typeof window.smartCaptcha !== "undefined") {
                    clearInterval(checkInterval);
                    self.renderWidget(sitekey, containerId);
                } else if (attempts >= maxAttempts) {
                    clearInterval(checkInterval);
                    Notification.addNotification({
                        message: "Captcha failed to load. Please refresh the page.",
                        type: "error"
                    });
                }
            }, 100);
        },

        renderWidget: function(sitekey, containerId) {
            var container = document.getElementById(containerId);
            if (!container) {
                return;
            }

            try {
                this.widgetId = window.smartCaptcha.render(container, {
                    sitekey: sitekey,
                    hl: this.getLanguage(),
                    callback: this.onSuccess.bind(this),
                    "expired-callback": this.onExpired.bind(this)
                });
            } catch (e) {
                // Render error handled silently.
            }
        },

        onSuccess: function(token) {
            var input = document.querySelector('input[name="smartcaptcha_token"]');
            if (input) {
                input.value = token;
            }
        },

        onExpired: function() {
            var input = document.querySelector('input[name="smartcaptcha_token"]');
            if (input) {
                input.value = "";
            }
            if (this.widgetId !== null && window.smartCaptcha) {
                window.smartCaptcha.reset(this.widgetId);
            }
        },

        getLanguage: function() {
            var lang = document.documentElement.lang || "en";
            var supported = ["ru", "en", "be", "kk", "tt", "uk", "uz", "tr"];
            
            lang = lang.split("-")[0];
            return supported.includes(lang) ? lang : "en";
        }
    };
});